void Step1()
{
    int Solve(string[] manifold)
    {
        if (manifold == null || manifold.Length == 0) return 0;

        int width = manifold[0].Length;
        int height = manifold.Length;

        int startColumn = manifold[0].IndexOf('S');
        if (startColumn == -1) return 0;

        bool[] prev = new bool[width];
        prev[startColumn] = true;

        int totalSplits = 0;

        for (int row = 1; row < height; row++)
        {
            bool[] curr = new bool[width];

            for (int col = 0; col < width; col++)
            {
                if (!prev[col]) continue;

                if (manifold[row][col] == '^')
                {
                    totalSplits++;

                    if (col > 0) curr[col - 1] = true;
                    if (col < width - 1) curr[col + 1] = true;
                }
                else
                {
                    curr[col] = true;
                }
            }

            prev = curr;
        }

        return totalSplits;
    }

