void Step2()
{
    long Solve(string[] map)
    {
        int H = map.Length;
        int W = map[0].Length;

        int start = map[0].IndexOf('S');

        long[] prev = new long[W];
        prev[start] = 1;

        for (int r = 1; r < H; r++)
        {
            long[] curr = new long[W];

            for (int c = 0; c < W; c++)
            {
                long t = prev[c];
                if (t == 0) continue;

                if (map[r][c] == '^')
                {
                    if (c > 0) curr[c - 1] += t;
                    if (c < W - 1) curr[c + 1] += t;
                }
                else
                {
                    curr[c] += t;
                }
            }

            prev = curr;
        }

        return prev.Sum();
    }

